const input = document.querySelector('.title-input');
const button = document.querySelector('.save-title');
const saved = document.querySelector('.saved-title');
button.addEventListener('click', () => {
  localStorage.setItem('practice:title', input.value);
  saved.textContent = localStorage.getItem('practice:title');
});
